<script id="pinlock-pure">
var PL = (function () {
  'use strict';
  var DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  var MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  function pad2(n) { return (n < 10 ? '0' : '') + n; }
  function lockText(l) { return 'Locked for ' + (l >= 60 ? Math.ceil(l / 60) + ' min' : l + ' s'); }
  function clock(s) { s = Math.max(0, Math.ceil(Number(s) || 0)); return Math.floor(s / 60) + ':' + pad2(s % 60); }
  // Dots to draw: at least 4, never fewer than digits typed, at most 8.
  function dotCount(len) { return Math.min(8, Math.max(4, len | 0)); }
  function stateLabel(s) { s = String(s || '').replace(/_/g, ' '); return s ? s.charAt(0).toUpperCase() + s.slice(1) : ''; }
  function stateKind(s) { return s === 'active' ? 'ok' : (s === 'disabled' ? 'plain' : 'warn'); }
  // Days are 1..7 = Sun..Sat. Empty or all seven means every day.
  function scheduleText(c) {
    var d = (c.days || []).slice().sort(function (a, b) { return a - b; });
    var days = (!d.length || d.length === 7) ? 'Every day' : d.map(function (n) { return DAYS[n - 1]; }).join(', ');
    var hrs = (c.from || c.to) ? (c.from || '00:00') + '–' + (c.to || '24:00') : 'all day';
    return days + ' · ' + hrs;
  }
  function expiryText(expires, now) {
    if (!expires) return '';
    var x = new Date(expires * 1000);
    return (expires * 1000 < now ? 'Expired ' : 'Expires ') + x.getDate() + ' ' + MON[x.getMonth()];
  }
  function roleClass(r) { return ['owner', 'staff', 'vendor', 'guest'].indexOf(r) >= 0 ? r : 'guest'; }
  return { DAYS: DAYS, lockText: lockText, clock: clock, dotCount: dotCount, stateLabel: stateLabel, stateKind: stateKind, scheduleText: scheduleText, expiryText: expiryText, roleClass: roleClass };
})();
</script>
<script>
(function () {
  'use strict';
  // The page holds no secret. A PIN lives in a JS variable only while being
  // typed, goes in a POST body (never the URL), and is cleared on send.
  var params = {};
  String(window.location.search).replace(/^\?/, '').split('&').forEach(function (p) {
    if (!p) return; var kv = p.split('='); params[decodeURIComponent(kv[0])] = decodeURIComponent((kv[1] || '').replace(/\+/g, ' '));
  });
  var base = params.relay || (window.location.protocol.indexOf('http') === 0 ? window.location.origin : '');
  var token = params.k || '';
  var $ = function (id) { return document.getElementById(id); };
  var cfg = null, session = '', adminState = null, pin = '', padAction = null, padMode = '';
  var DAYS = PL.DAYS, lockText = PL.lockText, resTimer = null, cdTimer = null;
  var reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  function el(tag, cls, text) { var e = document.createElement(tag); if (cls) e.className = cls; if (text !== undefined) e.textContent = text; return e; }
  function svg(id) { var w = el('span'); w.style.display = 'contents'; w.innerHTML = '<svg class="i"><use href="#' + id + '"/></svg>'; return w; }
  function toast(text, kind) {
    var t = $('toast'); t.textContent = text; t.className = kind || ''; t.style.display = 'block';
    clearTimeout(t._h); t._h = setTimeout(function () { t.style.display = 'none'; }, 3200);
  }
  function api(method, path, body) {
    if (!base) return Promise.reject(new Error('no relay address in the page URL'));
    var url = base + path + '?k=' + encodeURIComponent(token);
    var opts = { method: method, headers: {} };
    if (body !== undefined) { opts.headers['Content-Type'] = 'application/json'; opts.body = JSON.stringify(body); }
    return fetch(url, opts).then(function (r) { return r.json().then(function (j) { j._status = r.status; return j; }); });
  }

  // ── result overlay (granted / denied / locked) ──
