  function showResult(kind, title, sub, seconds) {
    hideResult();
    var s = $('resSheet'); s.innerHTML = '';
    var box = el('div', 'res' + (kind === 'ok' ? '' : ' bad'));
    var big = el('div', 'big'); big.appendChild(svg(kind === 'ok' ? 'i-check' : 'i-x'));
    box.appendChild(big); box.appendChild(el('h2', '', title));
    if (sub) box.appendChild(el('div', 'muted', sub));
    var cd = null;
    if (seconds > 0) { cd = el('div', 'cd', PL.clock(seconds)); box.appendChild(cd); }
    var ok = el('button', 'primary', 'OK'); ok.style.marginTop = '16px'; ok.onclick = hideResult; box.appendChild(ok);
    s.appendChild(box); $('resModal').style.display = 'flex';
    $('resModal').onclick = function (e) { if (e.target === $('resModal')) hideResult(); };
    if (kind === 'ok') resTimer = setTimeout(hideResult, 2200);
    else if (seconds > 0) {
      var end = Date.now() + seconds * 1000;
      cdTimer = setInterval(function () {
        var left = Math.ceil((end - Date.now()) / 1000);
        if (left <= 0) { hideResult(); loadConfig(); return; }
        cd.textContent = PL.clock(left);
      }, 1000);
    } else resTimer = setTimeout(hideResult, 3000);
  }

  // ── tabs ──
  function show(view) {
    $('viewKeypad').style.display = view === 'keypad' ? '' : 'none';
    $('viewAdmin').style.display = view === 'admin' ? '' : 'none';
    $('tabKeypad').className = view === 'keypad' ? 'on' : '';
    $('tabAdmin').className = view === 'admin' ? 'on' : '';
    if (view === 'admin') renderAdmin(); else loadConfig();
  }
  $('tabKeypad').onclick = function () { show('keypad'); };
  $('tabAdmin').onclick = function () { show('admin'); };

  // ── keypad ──
  function loadConfig() {
    api('GET', '/config').then(function (c) {
      cfg = c; renderActions();
    }).catch(function (e) { $('actions').innerHTML = ''; $('actions').appendChild(el('p', 'muted', 'Cannot reach the controller: ' + e.message)); });
  }
  function renderActions() {
    var box = $('actions'); box.innerHTML = '';
    $('mode').textContent = cfg.restricted ? 'Licence: owner codes only' : '';
    if (!cfg.actions.length) { box.appendChild(el('p', 'muted', 'No guarded actions yet. Name them in the driver properties in Composer.')); return; }
    var pageLock = cfg.locks.page;
    if (pageLock.locked) {
      var hero = el('div', 'card hero bad');
      hero.appendChild(el('b', '', 'Keypad locked after too many wrong codes'));
      hero.appendChild(el('div', '', lockText(pageLock.seconds) + '.'));
