      grid.appendChild(b);
    });
    box.appendChild(grid);
  }
  function dots() {
    var d = $('padDots'); d.innerHTML = '';
    var n = PL.dotCount(pin.length);
    for (var i = 0; i < n; i++) d.appendChild(el('i', i < pin.length ? 'on' : ''));
