    $('padModal').style.display = 'flex'; padCb = cb || null;
  }
  var padCb = null;
  function closePad() { $('padModal').style.display = 'none'; pin = ''; dots(); }
  (function buildPad() {
    var pad = $('pad');
    ['1','2','3','4','5','6','7','8','9','⌫','0','C'].forEach(function (k) {
      var b = el('button', (k === '⌫' || k === 'C') ? 'fn' : '', k);
