      typed = '';
      if (r.ok) { showResult('ok', r.message || 'Done', padAction.name); toast(r.message || 'Done', 'ok'); }
      else if (r.locked) { showResult('bad', 'Too many wrong codes', 'Try again in', r.retry_in || 0); loadConfig(); }
      else { showResult('bad', 'Not allowed', 'That code cannot do this right now.'); toast('Not allowed', 'bad'); }
    }).catch(function (e) { toast('Could not reach the controller', 'bad'); });
  };

  // ── admin ──
  function renderAdmin() {
    var box = $('admin'); box.innerHTML = '';
    if (!cfg) { api('GET', '/config').then(function (c) { cfg = c; renderAdmin(); }); return; }
    if (cfg.setup_needed) { setupForm(box); return; }
    if (!session) {
      var card = el('div', 'card');
      card.appendChild(el('div', 'name', 'Owner PIN needed to manage codes.'));
      if (cfg.locks.admin.locked) card.appendChild(el('div', 'chip bad', lockText(cfg.locks.admin.seconds)));
      var b = el('button', 'primary add', 'Sign in with an owner PIN');
      b.onclick = function () {
        openPad({ name: 'Owner sign-in' }, 'login', 'Owner PIN', function (typed) {
          api('POST', '/admin/login', { pin: typed }).then(function (r) {
            typed = '';
            if (r.ok) { session = r.session; loadAdmin(); }
            else if (r.locked) showResult('bad', 'Too many wrong codes', 'Try again in', r.retry_in || 0);
            else toast('Not allowed', 'bad');
          });
        });
      };
      card.appendChild(b); box.appendChild(card);
      return;
    }
    loadAdmin();
  }
  function setupForm(box) {
    var card = el('div', 'card');
    card.appendChild(el('div', 'name', 'First owner code'));
    card.appendChild(el('p', 'muted', 'No owner code exists yet. Create one now: it manages every other code. Anyone who can open this page can do this once, so do it before handing the system over.'));
    var n = el('input'); n.type = 'text'; n.placeholder = 'Name, e.g. Owner'; n.maxLength = 40;
    var p = el('input'); p.type = 'password'; p.inputMode = 'numeric'; p.placeholder = '4 to 8 digits'; p.autocomplete = 'off';
    var go = el('button', 'primary add', 'Create owner code');
    go.onclick = function () {
      api('POST', '/admin/setup', { name: n.value, pin: p.value }).then(function (r) {
        p.value = '';
        if (r.ok) { cfg.setup_needed = false; session = r.session || ''; toast('Owner code created', 'ok'); renderAdmin(); }
        else toast(r.error || 'Refused', 'bad');
      });
    };
    card.appendChild(el('label', '', 'Name')); card.appendChild(n);
    card.appendChild(el('label', '', 'PIN')); card.appendChild(p);
    go.style.marginTop = '16px'; card.appendChild(go); box.appendChild(card);
  }
  function loadAdmin() {
    api('POST', '/admin/state', { session: session }).then(function (r) {
      if (!r.ok) { session = ''; toast('Signed out', 'bad'); renderAdmin(); return; }
      adminState = r; drawAdmin();
    });
  }
  function drawAdmin() {
    $('editModal').style.display = 'none';
    var box = $('admin'); box.innerHTML = '';
    var s = adminState;
    var top = el('div', 'row');
    var cnt = el('div'); cnt.appendChild(el('div', 'name', s.codes.length + (s.codes.length === 1 ? ' code' : ' codes')));
    if (s.restricted) cnt.appendChild(el('div', 'sub', 'Licence restricted: no new access can be added'));
    top.appendChild(cnt);
    var out = el('button', '', 'Sign out'); out.onclick = function () { api('POST', '/admin/logout', { session: session }); session = ''; renderAdmin(); };
    top.appendChild(out); box.appendChild(top);
    var add = el('button', 'primary add', ''); add.appendChild(svg('i-plus')); add.appendChild(document.createTextNode('Add a code')); add.onclick = function () { editor(null); }; box.appendChild(add);
    s.codes.forEach(function (c) {
      var card = el('div', 'card code' + (c.enabled ? '' : ' off'));
      var av = el('div', 'av'); av.appendChild(svg('i-user')); card.appendChild(av);
      var body = el('div', 'body');
      var head = el('div', 'row');
      var nm = el('div', 'name', c.name); head.appendChild(nm);
      var sw = el('button', 'sw'); sw.setAttribute('role', 'switch'); sw.setAttribute('aria-checked', c.enabled ? 'true' : 'false'); sw.setAttribute('aria-label', (c.enabled ? 'Disable ' : 'Enable ') + c.name);
      sw.onclick = function () { post(c.enabled ? '/admin/disable' : '/admin/enable', { id: c.id }); };
      head.appendChild(sw); body.appendChild(head);
      var chips = el('div', 'chiprow');
      chips.appendChild(el('span', 'role ' + PL.roleClass(c.role), c.role));
      chips.appendChild(el('span', 'chip ' + PL.stateKind(c.state), PL.stateLabel(c.state)));
      var ex = PL.expiryText(c.expires, Date.now()); if (ex) chips.appendChild(el('span', 'chip plain', ex));
      if (c.max_uses) chips.appendChild(el('span', 'chip plain', c.uses + '/' + c.max_uses + ' uses'));
      if (c.has_pin) chips.appendChild(el('span', 'chip plain', 'PIN'));
      if (c.has_seq) chips.appendChild(el('span', 'chip plain', 'Keypad sequence'));
      body.appendChild(chips);
      body.appendChild(el('div', 'sub', PL.scheduleText(c)));
      var names = c.role === 'owner' ? 'All actions' : c.actions.map(function (n) { var a = s.actions.filter(function (x) { return x.n === n; })[0]; return a ? a.name : '#' + n; }).join(', ');
      body.appendChild(el('div', 'sub', names || 'No actions'));
      var btns = el('div', 'tools');
      var e = el('button', '', 'Edit'); e.onclick = function () { editor(c); };
      var d = el('button', 'danger', 'Revoke'); d.onclick = function () { if (confirm('Revoke ' + c.name + '? This removes the code.')) post('/admin/revoke', { id: c.id }); };
      btns.appendChild(e); btns.appendChild(d); body.appendChild(btns);
      card.appendChild(body); box.appendChild(card);
    });
    box.appendChild(el('h2', 'sec', 'Entry points'));
    var ep = el('div', 'chiprow');
    ['page', 'keypad', 'admin'].forEach(function (k) {
      var l = s.locks[k];
      ep.appendChild(el('span', 'chip ' + (l.locked ? 'bad' : 'ok'), k + ': ' + (l.locked ? lockText(l.seconds) : 'open')));
    });
    box.appendChild(ep);
    var clr = el('button', 'danger', 'Clear lockouts'); clr.style.marginTop = '10px'; clr.onclick = function () { post('/admin/clear', {}); };
    box.appendChild(clr);
    box.appendChild(el('h2', 'sec', 'Recent attempts (names only, never PINs)'));
    if (!s.recent.length) box.appendChild(el('div', 'muted', 'None since the last restart'));
    var tl = el('ul', 'tl');
    s.recent.forEach(function (x) {
      var li = el('li', x.result === 'granted' ? 'granted' : (x.result === 'denied' ? 'denied' : 'locked'));
      li.appendChild(el('div', 'w', (x.code || 'Unknown code') + (x.action ? ' · ' + x.action : '')));
      li.appendChild(el('div', 't', new Date(x.t * 1000).toLocaleTimeString() + ' · ' + x.result + ' · ' + x.entry + (x.reason ? ' (' + x.reason + ')' : '')));
      tl.appendChild(li);
    });
    box.appendChild(tl);
  }
  function post(path, body) {
    body.session = session;
    api('POST', path, body).then(function (r) {
      if (r.ok) { toast('Saved', 'ok'); loadAdmin(); } else toast(r.error || 'Refused', 'bad');
    });
  }
  function fld(label, node) { var w = el('div'); w.appendChild(el('label', '', label)); w.appendChild(node); return w; }
  function editor(c) {
    var s = adminState, box = $('editSheet'); box.innerHTML = '';
    var d = c || { name: '', role: 'guest', actions: [], days: [], from: '', to: '', max_uses: '', keypad_action: '' };
    var name = el('input'); name.type = 'text'; name.maxLength = 40; name.value = d.name;
    var role = el('select'); ['owner', 'staff', 'vendor', 'guest'].forEach(function (r) { var o = el('option', '', r); o.value = r; if (r === d.role) o.selected = true; role.appendChild(o); });
    var pinIn = el('input'); pinIn.type = 'password'; pinIn.inputMode = 'numeric'; pinIn.autocomplete = 'off'; pinIn.placeholder = c && c.has_pin ? 'leave empty to keep' : '4 to 8 digits';
    var seqIn = el('input'); seqIn.type = 'password'; seqIn.autocomplete = 'off'; seqIn.placeholder = c && c.has_seq ? 'leave empty to keep' : 'optional, e.g. 1-3-3-2';
    box.appendChild(el('h2', '', c ? 'Edit ' + c.name : 'New code'));
    box.appendChild(fld('Name', name)); box.appendChild(fld('Role (owner can manage codes and fires every action)', role));
    box.appendChild(fld('PIN', pinIn)); box.appendChild(fld('Keypad sequence (' + s.sequence_length + ' button ids)', seqIn));
    var acts = el('div', 'chips'); var boxes = [];
    s.actions.forEach(function (a) {
      var l = el('label'); var cb = el('input'); cb.type = 'checkbox'; cb.checked = d.actions.indexOf(a.n) >= 0; cb.value = a.n; boxes.push(cb);
      l.appendChild(cb); l.appendChild(document.createTextNode(a.name)); acts.appendChild(l);
    });
    box.appendChild(fld('May fire', acts));
    var ka = el('select'); var none = el('option', '', 'first allowed'); none.value = ''; ka.appendChild(none);
    s.actions.forEach(function (a) { var o = el('option', '', a.name); o.value = a.n; if (d.keypad_action === a.n) o.selected = true; ka.appendChild(o); });
    box.appendChild(fld('Keypad sequence fires', ka));
    var days = el('div', 'chips'); var dayBoxes = [];
    DAYS.forEach(function (n, i) {
      var l = el('label'); var cb = el('input'); cb.type = 'checkbox'; cb.value = i + 1; cb.checked = !d.days.length || d.days.indexOf(i + 1) >= 0; dayBoxes.push(cb);
      l.appendChild(cb); l.appendChild(document.createTextNode(n)); days.appendChild(l);
    });
    box.appendChild(fld('Days', days));
    var from = el('input'); from.type = 'time'; from.value = d.from || ''; var to = el('input'); to.type = 'time'; to.value = d.to || '';
    var g = el('div', 'grid2'); g.appendChild(fld('From (empty = all day)', from)); g.appendChild(fld('To', to)); box.appendChild(g);
    function ymd(t) { if (!t) return ''; var x = new Date(t * 1000); return x.getFullYear() + '-' + ('0' + (x.getMonth() + 1)).slice(-2) + '-' + ('0' + x.getDate()).slice(-2); }
    var sd = el('input'); sd.type = 'date'; sd.value = ymd(d.starts); var ed = el('input'); ed.type = 'date'; ed.value = ymd(d.expires);
    var g2 = el('div', 'grid2'); g2.appendChild(fld('Starts', sd)); g2.appendChild(fld('Expires (end of day)', ed)); box.appendChild(g2);
    var mu = el('input'); mu.type = 'number'; mu.min = 1; mu.max = 9999; mu.value = d.max_uses || ''; mu.placeholder = 'no limit';
    box.appendChild(fld('Max uses', mu));
    var bar = el('div', 'bar'); var cancel = el('button', '', 'Cancel'); cancel.onclick = function () { pinIn.value = ''; seqIn.value = ''; $('editModal').style.display = 'none'; };
    var save = el('button', 'primary', 'Save');
    save.onclick = function () {
      var doc = {
        session: session, id: c ? c.id : undefined, name: name.value, role: role.value, pin: pinIn.value, seq: seqIn.value,
        actions: boxes.filter(function (b) { return b.checked; }).map(function (b) { return Number(b.value); }),
        keypad_action: ka.value === '' ? '' : Number(ka.value),
        days: dayBoxes.every(function (b) { return b.checked; }) ? [] : dayBoxes.filter(function (b) { return b.checked; }).map(function (b) { return Number(b.value); }),
        from: from.value, to: to.value, start_date: sd.value, expiry_date: ed.value, max_uses: mu.value === '' ? '' : Number(mu.value)
      };
      api('POST', '/admin/save', doc).then(function (r) {
        pinIn.value = ''; seqIn.value = ''; doc.pin = ''; doc.seq = '';
        if (r.ok) { toast('Saved', 'ok'); loadAdmin(); } else toast(r.error || 'Refused', 'bad');
      });
    };
    bar.appendChild(cancel); bar.appendChild(save); box.appendChild(bar);
    $('editModal').style.display = 'flex';
  }

  loadConfig();
  setInterval(function () { if ($('viewKeypad').style.display !== 'none' && $('padModal').style.display !== 'flex' && $('resModal').style.display !== 'flex') loadConfig(); }, 20000);
})();
</script>
</body>
</html>
